import java.util.concurrent.locks.ReentrantLock;

public class PinningMitigationService {
    // BAD: Using 'synchronized' causes the virtual thread to pin the carrier thread during I/O
    private final Object legacyLock = new Object();

    public void legacySynchronizedMethod() {
        synchronized (legacyLock) {
            // If this blocks on I/O, the carrier thread is pinned!
            blockingIoOperation();
        }
    }

    // GOOD: Using java.util.concurrent.locks.ReentrantLock allows virtual thread unmounting
    private final ReentrantLock modernLock = new ReentrantLock();

    public void modernLockedMethod() {
        modernLock.lock();
        try {
            // If this blocks on I/O, the virtual thread safely unmounts from the carrier
            blockingIoOperation();
        } finally {
            modernLock.unlock();
        }
    }

    private void blockingIoOperation() {
        // Simulated blocking operation
    }
}
